	/** 
	 * jumpstart the process by instantiating2 Wallet
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		walletId = WalletService.getWalletInstance()
		.createWallet( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		WalletService.getWalletInstance()
				.createWallet( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.walletSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Wallet : " + successValue.getWalletId());
							  if (successValue.getWalletId().equals(walletId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfWalletList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Wallet test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on wallet consumed")
					);
			subscriber.walletSubscribe( walletId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Wallet : " + successValue.getWalletId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfWalletList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on wallet for walletId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Wallet. 
	 */
	protected Wallet read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Wallet" );

		Wallet entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Wallet with primary key" );
		msg.append( walletId );
		
		WalletFetchOneSummary fetchOneSummary = new WalletFetchOneSummary( walletId );

		try {
			entity = WalletService.getWalletInstance().getWallet( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Wallet " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Wallet.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Wallet." );

		StringBuilder msg = new StringBuilder( "Failed to update a Wallet : " );        
		Wallet entity = read();
		UpdateWalletCommand command = generateUpdateCommand();
		command.setWalletId(entity.getWalletId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Wallet." );

			// for use later on...
			walletId = entity.getWalletId();

			WalletService proxy = WalletService.getWalletInstance();  

			proxy.updateWallet( command ).get();

			LOGGER.info( "-- Successfully saved Wallet - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + walletId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Wallet.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Wallet." );

		Wallet entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Wallet with id " + walletId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Wallet with id " + walletId );

			throw e;
		}

		try{
			WalletService.getWalletInstance().delete( new DeleteWalletCommand( entity.getWalletId() ) ).get();
			LOGGER.info( "-- Successfully deleted Wallet with id " + walletId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Wallet with id " + walletId );

			throw e;
		}
	}

	/**
	 * get all Wallets.
	 */
	protected List<Wallet> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Wallets:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Wallet : " );        
		List<Wallet> collection  = new ArrayList<>();

		try {
			// call the static get method on the WalletService
			collection = WalletService.getWalletInstance().getAllWallet();
			assertNotNull( collection, "An Empty collection of Wallet was incorrectly returned.");
			
			// Now print out the values
			Wallet entity = null;            
			Iterator<Wallet> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getWalletId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

